/* ══════════════════════════════════════════════════════════════════════════
   TIRI · ASSETS
   The only rasters in the prototype, inlined as data URIs.

   Inlined rather than linked because this folder is design EVIDENCE — a record
   with a broken image is worse than a record that is 90KB heavier. Sources are
   tracked in the repo at assets/{F&F - Dark.png, Sylvain.png, Warren.png};
   these are downscaled (photos 320px JPEG q72, the mark 620px PNG).

   The photos are duotoned in CSS by `mix-blend-mode:luminosity` over a solid
   brand colour, which is the only route to a true duotone — a filter chain
   cannot map a photograph's mid-tones onto one hue without flattening them.
   ══════════════════════════════════════════════════════════════════════════ */
const IMG_MARK="data:image/png;base64,";

const IMG_TEAM={
  sylvain:"data:image/jpeg;base64,",

  warren:"data:image/jpeg;base64,"
};

/* ── THE ICON SET ──────────────────────────────────────────────────────────
   39 transparent 100x100 PNGs, copied into `tiri/assets/` and referenced by
   relative path rather than inlined. The source of truth is the repository's own
   `/assets` — see `assets/ICON_SOURCES.md` for what each one is and where it came
   from; these are copies because the prototype's document root is `tiri/` and a
   `../../../../assets/` reference escapes it, which the server refuses and a
   reader of a self-contained folder should not have to think about.

   Not base64 like the mark and the portraits: 39 files is 212KB on disk and about
   285KB inlined, which would have made `assets.js` the largest file in a split
   whose entire purpose was to stop files being too large to read.

   The two industry illustrations arrived at 1254px and are downscaled to 320 —
   they are drawn at ~120px, so the rest was four times the pixels for nothing.

   `ICO(name)` returns a path from a slug. A missing file returns null so a caller
   can fall back rather than render a broken image. */
const ICON_DIR='assets/';
/* AN EXPLICIT MAP, NOT A SLUG FUNCTION. The obvious lower-case-and-hyphenate rule
   resolved 34 of 39 and silently failed on the rest: `StratifiedKFold` has no word
   break to hyphenate, `recall@k` and `WSS@95` spell the at-sign out in the filename,
   and a combined label like "React · Mantine" is two marks rather than one file. A
   rule that is right most of the time returns null the rest of the time, and a
   missing icon is exactly the kind of failure nobody notices in review.
   One line per mark. `ICO()` returns null for anything absent, so a caller can fall
   back rather than render a broken image. */
const ICON_FILE={
  'OpenAlex':'openalex', 'Crossref':'crossref', 'Semantic Scholar':'semantic-scholar',
  'Europe PMC':'europe-pmc', 'PubMed':'pubmed', 'arXiv':'arxiv', 'CORE':'core',
  'MiniLM-L12-v2':'minilm-l12-v2', 'bge-small-en-v1.5':'bge-small-en-v1-5',
  'fastembed':'fastembed', 'ONNX Runtime':'onnx-runtime', 'pgvector':'pgvector',
  'scikit-learn':'scikit-learn', 'NumPy':'numpy', 'Rocchio centroid':'rocchio-centroid',
  'StratifiedKFold':'stratified-kfold', 'recall@k':'recall-at-k', 'WSS@95':'wss-at-95',
  'Leave-one-out':'leave-one-out',
  'OpenRouter':'openrouter', 'Claude Sonnet 4.6':'claude-sonnet-4-6', 'httpx':'httpx',
  'Versioned prompts':'versioned-prompts',
  'FastAPI':'fastapi', 'Pydantic':'pydantic', 'PostgreSQL':'postgresql', 'React':'react',
  'Mantine':'mantine', 'TanStack Query':'tanstack-query', 'pypdf':'pypdf',
  'Playwright':'playwright', 'pytest':'pytest',
  'Nemotron':'nvidia', 'GPT OSS':'gpt-oss', 'PostGres':'postgresql', 'Qwen3':'qwen',
  'Jasper 600m':'jasper-600m', 'Optuna':'optuna', 'pgVec':'pgvector',
  'Sources':'category-sources', 'Text into vectors':'category-text-into-vectors',
  'Ranking and learning':'category-ranking-and-learning',
  'Language models':'category-language-models', 'The application':'category-application',
  'Efficient industry':'efficient-industry', 'Inefficient industry':'inefficient-industry'
};
const ICO=nm=>ICON_FILE[nm]? ICON_DIR+'icon-'+ICON_FILE[nm]+'.png' : null;
